\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Neuroscience Color Theme (Deep Navy + Electric Blue / Teal / Gold) ──
\definecolor{primary}{HTML}{0F1B2D}        % deep navy (title bar, primary)
\definecolor{secondary}{HTML}{0E7490}       % teal (secondary accents)
\definecolor{accent}{HTML}{3B82F6}          % electric blue (accent)
\definecolor{gold}{HTML}{F59E0B}            % warm gold (highlight accent)
\definecolor{bgposter}{HTML}{111827}        % dark charcoal background
\definecolor{navylight}{HTML}{1E293B}       % slightly lighter navy for card bgs
\definecolor{cardbg}{HTML}{1A2332}          % dark card background
\definecolor{cardbg2}{HTML}{172032}         % alternate card background
\definecolor{cardbg3}{HTML}{1C2536}         % third card background
\definecolor{titlebg}{HTML}{0D1524}         % title bar card bg
\definecolor{textlight}{HTML}{F1F5F9}       % near-white text
\definecolor{textgray}{HTML}{94A3B8}        % muted gray text
\definecolor{textdim}{HTML}{CBD5E1}         % slightly brighter gray
\definecolor{stathighlight}{HTML}{172554}   % deep blue for stat callout bg
\definecolor{statgold}{HTML}{422006}        % deep gold tint for stat bg
\definecolor{divider}{HTML}{334155}         % subtle divider color

\pagecolor{bgposter}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{gold}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (dark theme with left accent stripes) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  tealcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg2,
    borderline west={5pt}{0pt}{secondary},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=cardbg2,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  darkcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=cardbg3,
    borderline west={5pt}{0pt}{gold},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=cardbg3,
    toptitle=8pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={gold!40},
    valign=top, drop shadow={opacity=0.25,color=black},
  },
  highlightcard/.style={
    enhanced, arc=2pt, boxrule=0pt, colback=stathighlight,
    borderline west={6pt}{0pt}{accent},
    left=16pt, right=14pt, top=6pt, bottom=6pt,
    fonttitle=\fontsize{40}{48}\selectfont\bfseries\color{textlight},
    coltitle=textlight, colbacktitle=primary,
    toptitle=8pt, bottomtitle=6pt,
    valign=top, drop shadow={opacity=0.30,color=black},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ════════════════════════════════════════════════
% ══ TITLE BAR (row 0-4, span=3) ══
% ════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textlight,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=16pt, bottom=10pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4,color=black}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{22}{28}\selectfont\color{gold}\bfseries NATURE 2024 \quad$\vert$\quad DOI: 10.1038/s41586-024-07487-w}\\[12pt]
  {\fontsize{76}{92}\selectfont\bfseries\color{textlight} Mapping Neural Circuit Architecture:\\[6pt] Advances in Brain Connectivity Analysis}\\[14pt]
  {\fontsize{34}{42}\selectfont\color{textgray} Large-Scale Connectomics Reveals New Principles of Neural Circuit Organization}\\[10pt]
  {\fontsize{30}{38}\selectfont\color{accent} Neuroscience Symposium \quad$\vert$\quad Nature Research Conference 2024}
}

% ════════════════════════════════════════════════
% ══ STAT BANNER (row 4-6, span=3) ══
% ════════════════════════════════════════════════
\posterbox[
  enhanced, colback=navylight, boxrule=0pt, arc=0pt,
  left=20pt, right=20pt, top=10pt, bottom=10pt,
  valign=center, borderline south={3pt}{0pt}{accent!50},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  % Stat 1: Neurons Mapped
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{accent} $\sim$125K}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdim} Neurons Mapped}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Stat 2: Synaptic Connections
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{statgold}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{gold} $\sim$54M}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdim} Synaptic Connections}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Stat 3: Circuit Motifs
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!40}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{accent} 37}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdim} Circuit Motifs Identified}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  % Stat 4: Classification Accuracy
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!40}{statgold}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{62}{76}\selectfont\bfseries\color{gold} 94.2\%}\\[4pt]
      {\fontsize{26}{32}\selectfont\color{textdim} Classification Accuracy}\vspace{8pt}%
    }}
  \end{minipage}
}

% ════════════════════════════════════════════════
% ══ COLUMN 1 ══
% ════════════════════════════════════════════════

% ── Background & Motivation (row 6-11) ──
\posterbox[tealcard, title={Background \& Motivation}
]{name=background, column=1, between=row6 and row11}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \begin{itemize}[itemsep=12pt]
    \item Brain info processing requires detailed connectivity maps
    \item Classical neuroanatomy lacked resolution and scale
    \item Gap between structural wiring and functional organization
  \end{itemize}
  \vspace{6pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{gold}Key Insight:} EM + ML + computational neuroscience converge to make large-scale connectomics feasible
    \vspace{4pt}
  }}
}

% ── Methodology Pipeline (row 11-17) ──
\posterbox[bluecard, title={Methodology Pipeline}
]{name=methods, column=1, between=row11 and row17}{
  \fontsize{30}{38}\selectfont\color{textlight}

  % Pipeline steps as colorboxes
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{accent}1. Imaging} $\to$ Serial-section EM at 4$\times$4$\times$30\,nm resolution\vspace{4pt}
  }}\\[8pt]
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{accent}2. Segmentation} $\to$ Deep learning neuron tracing + human proofreading\vspace{4pt}
  }}\\[8pt]
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{accent}3. Synapse Detection} $\to$ CNN classifier (94.2\% accuracy)\vspace{4pt}
  }}\\[8pt]
  \colorbox{accent!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{accent}4. Circuit Analysis} $\to$ Graph-theoretic motif detection + clustering\vspace{4pt}
  }}\\[8pt]
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{secondary}5. Validation} $\to$ Calcium imaging + optogenetic perturbation\vspace{4pt}
  }}
}

% ── References (row 17-20) ──
\posterbox[darkcard, title={Reference}
]{name=references, column=1, between=row17 and row20}{
  \fontsize{28}{36}\selectfont\color{textdim}
  \begin{itemize}[itemsep=6pt]
    \item Nature (2024). Neural Circuit Architecture at Scale. \textit{Nature}
    \item DOI: 10.1038/s41586-024-07487-w
    \item Open-access dataset + analysis tools available
  \end{itemize}
}

% ════════════════════════════════════════════════
% ══ COLUMN 2 (KEY FINDINGS — most prominent) ══
% ════════════════════════════════════════════════

% ── Key Findings: Motifs & Hubs (row 6-13) ──
\posterbox[highlightcard, title={Key Findings}
]{name=findings1, column=2, between=row6 and row13}{
  \fontsize{32}{42}\selectfont\color{textlight}

  % Finding 1: Motifs
  \colorbox{accent!25}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{accent}37 Distinct Connectivity Motifs}\\[3pt]
    Recurring building blocks suggest \textbf{modular wiring logic} --- a finite vocabulary of circuit elements, analogous to logic gates\vspace{4pt}
  }}\\[10pt]

  % Finding 2: Hub Neurons
  \colorbox{gold!25}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{gold}Hub Neurons: 3.5\% $\to$ 28\% Output}\\[3pt]
    Tiny fraction of neurons drive disproportionate synaptic output --- highly non-uniform distribution of influence\vspace{4pt}
  }}\\[10pt]

  % Finding 3: Layer-Specific Rules
  \colorbox{accent!25}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{accent}Layer-Specific Wiring Rules}\\[3pt]
    Feedforward: L2/3 $\to$ L4 dominant. Recurrent enriched in L5 with \textbf{4.7:1 ratio} (recurrent vs.\ feedforward)\vspace{4pt}
  }}\\[10pt]

  % Finding 4: Inhibitory Specificity
  \colorbox{gold!25}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{gold}Inhibitory Specificity: 6.2$\times$ Higher}\\[3pt]
    Interneurons connect with \textbf{6.2$\times$ higher specificity} than excitatory neurons --- challenges ``blanket inhibition'' assumption\vspace{4pt}
  }}
}

% ── Quantitative Summary Table (row 13-17) ──
\posterbox[bluecard, title={Quantitative Summary}
]{name=summary, column=2, between=row13 and row17}{
  \fontsize{30}{38}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.8}
  \begin{tabular}{p{0.50\linewidth}p{0.40\linewidth}}
    \rowcolor{accent!20}
    \textbf{\color{accent}Finding} & \textbf{\color{accent}Result} \\
    \rowcolor{navylight}
    Connectivity motifs & \textbf{\color{gold}37 distinct types} \\
    \rowcolor{accent!12}
    Hub neuron fraction & \textbf{\color{gold}3.5\% $\to$ 28\% output} \\
    \rowcolor{navylight}
    L5 recurrent ratio & \textbf{\color{gold}4.7:1} \\
    \rowcolor{accent!12}
    Inhibitory specificity & \textbf{\color{gold}6.2$\times$ vs.\ excitatory} \\
    \rowcolor{navylight}
    Total neurons & $\sim$125,000 \\
    \rowcolor{accent!12}
    Total synapses & $\sim$54 million \\
  \end{tabular}
}

% ── Key Takeaway (row 17-20) ──
\posterbox[highlightcard, title={Core Message}
]{name=takeaway, column=2, between=row17 and row20}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \centering
  \colorbox{gold!30}{\parbox{0.92\linewidth}{%
    \fontsize{32}{42}\selectfont\color{textlight}\centering
    The brain employs a \textbf{\color{gold}finite vocabulary} of circuit motifs --- modular wiring logic underlies cortical computation\vspace{4pt}
  }}
}

% ════════════════════════════════════════════════
% ══ COLUMN 3 ══
% ════════════════════════════════════════════════

% ── Implications (row 6-11) ──
\posterbox[darkcard, title={Implications}
]{name=implications, column=3, between=row6 and row11}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \begin{itemize}[itemsep=10pt]
    \item Modular motifs $=$ circuit ``logic gates'' for cortical computation
    \item Hub neurons explain how focal lesions produce widespread effects
    \item Direct relevance to neurological disease and BCI design
  \end{itemize}
  \vspace{4pt}
  \colorbox{gold!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{gold}Clinical Impact:} Targeted stimulation strategies informed by hub neuron mapping\vspace{4pt}
  }}
}

% ── Future Directions (row 11-15) ──
\posterbox[tealcard, title={Future Directions}
]{name=future, column=3, between=row11 and row15}{
  \fontsize{32}{42}\selectfont\color{textlight}
  \begin{enumerate}[itemsep=10pt]
    \item Extend connectomics to additional brain regions
    \item Cross-species comparative analysis
    \item Build complete mammalian brain wiring diagram
  \end{enumerate}
  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
    \fontsize{30}{38}\selectfont\color{textlight}
    \textbf{\color{secondary}Open Science:} Dataset + tools publicly released to accelerate discovery\vspace{4pt}
  }}
}

% ── Method Details (row 15-20) ──
\posterbox[bluecard, title={Technical Specifications}
]{name=techspecs, column=3, between=row15 and row20}{
  \fontsize{30}{38}\selectfont\color{textlight}
  \renewcommand{\arraystretch}{1.7}
  \begin{tabular}{p{0.35\linewidth}p{0.55\linewidth}}
    \rowcolor{accent!20}
    \textbf{\color{accent}Component} & \textbf{\color{accent}Specification} \\
    \rowcolor{navylight}
    Imaging & Serial-section EM \\
    \rowcolor{accent!12}
    Resolution & 4$\times$4$\times$30\,nm \\
    \rowcolor{navylight}
    Segmentation & DL + human proofreading \\
    \rowcolor{accent!12}
    Synapse CNN & 94.2\% accuracy \\
    \rowcolor{navylight}
    Analysis & Graph motif detection \\
    \rowcolor{accent!12}
    Validation & Calcium imaging + optogenetics \\
  \end{tabular}
}

\end{tcbposter}
\end{document}

